--
-- Table structure for table `detalleentrada`
--

DROP TABLE IF EXISTS `detalleentrada`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `detalleentrada` (
  `idDetalleEntrada` int(11) NOT NULL AUTO_INCREMENT,
  `idProducto` int(11) DEFAULT NULL,
  `CostoUnitario` decimal(8,2) DEFAULT NULL,
  `idEntrada` int(11) DEFAULT NULL,
  `idDetalleSalida` int(11) DEFAULT NULL,
  PRIMARY KEY (`idDetalleEntrada`),
  KEY `fk_DetalleEntrada_Producto1` (`idProducto`),
  KEY `fk_DetalleEntrada_Entrada1` (`idEntrada`),
  KEY `fk_DetalleEntrada_detalleSalida1` (`idDetalleSalida`),
